/**
 * Creates the demo workspace ("Demo Company") and its owner account. Idempotent.
 * Credentials come from SEED_OWNER_EMAIL / SEED_OWNER_PASSWORD in .env.local
 * (generated by `pnpm env:init`), never from source.
 */
import "./load-env";
import { eq, sql } from "drizzle-orm";
import { appendAudit } from "../src/server/audit/audit";
import { hashPassword } from "../src/server/auth/password";
import { closeDb, db } from "../src/server/db/client";
import { users, workspaces } from "../src/server/db/schema";

async function main() {
  const email = process.env.SEED_OWNER_EMAIL;
  const password = process.env.SEED_OWNER_PASSWORD;
  if (!email || !password) throw new Error("SEED_OWNER_EMAIL and SEED_OWNER_PASSWORD must be set (run pnpm env:init)");

  const existing = await db()
    .select()
    .from(users)
    .where(eq(sql`lower(${users.email})`, email.toLowerCase()))
    .limit(1);
  if (existing.length > 0) {
    console.log(`[seed] owner ${email} already exists`);
    return;
  }

  const passwordHash = await hashPassword(password);
  await db().transaction(async (tx) => {
    const [ws] = await tx.insert(workspaces).values({ name: "Demo Company", baseCurrency: "USD" }).returning();
    const [owner] = await tx
      .insert(users)
      .values({ workspaceId: ws.id, email, name: "Demo Company Owner", passwordHash, role: "OWNER" })
      .returning();
    await appendAudit(tx, {
      workspaceId: ws.id,
      actor: "system",
      kind: "workspace.created",
      summary: `Workspace "${ws.name}" created with owner ${owner.email}`,
      payload: { ownerId: owner.id },
    });
  });
  console.log(`[seed] created the Demo Company workspace and owner ${email}`);
}

main()
  .then(() => closeDb())
  .catch(async (err) => {
    console.error(err);
    await closeDb();
    process.exit(1);
  });
